<?php
$pageTitle='Manager workspace'; require_once 'includes/auth.php'; require_manager(); $u=current_user();
$s=$pdo->prepare('SELECT u.id,u.full_name,u.user_code,COUNT(DISTINCT t.id) ticket_count,COUNT(DISTINCT CASE WHEN t.status<>"Closed" THEN t.id END) open_count,COUNT(DISTINCT a.id) audio_count FROM users u LEFT JOIN tickets t ON t.assigned_to=u.id LEFT JOIN audio_logs a ON a.user_id=u.id WHERE u.company_id=? AND u.role<>"manager" GROUP BY u.id ORDER BY u.full_name');$s->execute([$u['company_id']]);$employees=$s->fetchAll();
$s=$pdo->prepare('SELECT t.*,p.name project_name,u.full_name assignee FROM tickets t JOIN projects p ON p.id=t.project_id LEFT JOIN users u ON u.id=t.assigned_to WHERE p.company_id=? ORDER BY FIELD(t.priority,"urgent","important","normal"),t.created_at DESC');$s->execute([$u['company_id']]);$tickets=$s->fetchAll();
$s=$pdo->prepare('SELECT a.*,u.full_name,p.name project_name FROM audio_logs a LEFT JOIN users u ON u.id=a.user_id LEFT JOIN projects p ON p.id=a.project_id WHERE a.company_id=? ORDER BY a.created_at DESC');$s->execute([$u['company_id']]);$audio=$s->fetchAll(); require 'includes/header.php';
?><style>.manager-banner{background:#0f172a;color:#fff;border-radius:9px;padding:25px 28px;display:flex;justify-content:space-between;align-items:center;gap:20px}.manager-banner h2{margin:0 0 8px;font-size:23px;letter-spacing:-.04em}.manager-banner .eyebrow{color:#cbd5e1}.manager-banner .muted{color:#cbd5e1}.manager-legend{display:flex;gap:8px;flex-wrap:wrap}.priority{display:inline-block;padding:4px 8px;border-radius:4px;font-size:10px;font-weight:800;text-transform:uppercase;letter-spacing:.04em}.priority.urgent{background:#fee2e2;color:#b91c1c}.priority.important{background:#fef3c7;color:#92400e}.priority.normal{background:#dcfce7;color:#166534}.employee-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.employee-card{padding:18px}.employee-name{display:flex;align-items:center;gap:10px}.employee-name h3{font-size:14px;margin:0 0 3px}.employee-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:20px;padding-top:15px;border-top:1px solid var(--line)}.employee-stats strong,.employee-stats span{display:block}.employee-stats strong{font-size:19px}.employee-stats span{font-size:9px;color:var(--muted);margin-top:3px}.manager-columns{display:grid;grid-template-columns:1.35fr .8fr;gap:18px}.manager-table{overflow:auto}.manager-recordings{padding:5px 18px}.recording-row{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:15px 0;border-bottom:1px solid var(--line)}.recording-row:last-child{border-bottom:0}.recording-row strong{font-size:12px}.recording-row audio{max-width:150px}@media(max-width:1000px){.employee-grid{grid-template-columns:repeat(2,1fr)}.manager-columns{grid-template-columns:1fr}}@media(max-width:600px){.employee-grid{grid-template-columns:1fr}.manager-banner{align-items:flex-start;flex-direction:column}}</style><div class="manager-banner"><div><p class="eyebrow">Leadership console</p><h2>Team workload & recordings</h2><p class="muted">Monitor ownership, urgency, delivery status, and meeting evidence.</p></div><div class="manager-legend"><span class="priority urgent">Urgent</span><span class="priority important">Important</span><span class="priority normal">Normal</span></div></div><div class="section-head"><h2>Employee workload</h2><span class="muted"><?=count($employees)?> employees</span></div><div class="employee-grid"><?php foreach($employees as $epl): ?><article class="card employee-card"><div class="employee-name"><div class="avatar"><?=e(strtoupper(substr($epl['full_name'],0,1)))?></div><div><h3><?=e($epl['full_name'])?></h3><span class="muted">@<?=e($epl['user_code'])?></span></div></div><div class="employee-stats"><div><strong><?=$epl['open_count']?></strong><span>Open tickets</span></div><div><strong><?=$epl['ticket_count']?></strong><span>Total tickets</span></div><div><strong><?=$epl['audio_count']?></strong><span>Recordings</span></div></div></article><?php endforeach; ?><?php if(!$employees): ?><div class="card empty">No member accounts exist yet.</div><?php endif; ?></div><div class="manager-columns"><section><div class="section-head"><h2>Assigned tickets</h2></div><div class="card manager-table"><table><thead><tr><th>Priority</th><th>Ticket</th><th>Project</th><th>Responsible employee</th><th>Status</th><th>Due</th></tr></thead><tbody><?php foreach($tickets as $t): ?><tr><td><span class="priority <?=e($t['priority'])?>"><?=ucfirst(e($t['priority']))?></span></td><td><strong><?=e($t['title'])?></strong></td><td><?=e($t['project_name'])?></td><td><?=e($t['assignee']?:'Unassigned')?></td><td><span class="badge badge-<?=strtolower($t['status'])==='closed'?'closed':'open'?>"><?=e($t['status'])?></span></td><td><?=e($t['expected_submit_date']?:'—')?></td></tr><?php endforeach; ?></tbody></table><?php if(!$tickets): ?><div class="empty">No tickets have been created.</div><?php endif; ?></div></section><section><div class="section-head"><h2>Team recordings</h2></div><div class="card manager-recordings"><?php foreach($audio as $a): ?><div class="recording-row"><div><strong><?=e($a['label']?:'Untitled recording')?></strong><div class="muted"><?=e($a['full_name']?:'Unknown employee')?> · <?=e($a['project_name']?:'Unassigned')?> · <?=e(date('M j, H:i',strtotime($a['created_at'])))?></div></div><audio controls preload="none" src="uploads/<?=e($a['filename'])?>"></audio></div><?php endforeach; ?><?php if(!$audio): ?><div class="empty">No team recordings yet.</div><?php endif; ?></div></section></div><?php require 'includes/footer.php';
